import { motion, AnimatePresence } from 'framer-motion';
import { useState } from 'react';

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.1 },
  },
};

const itemVariants = {
  hidden: { opacity: 0, y: 20 },
  visible: { opacity: 1, y: 0 },
};

const INITIAL_QUESTS = [
  { id: 1, title: 'Slay the Dragon' },
  { id: 2, title: 'Find the Tome' },
  { id: 3, title: 'Rescue the Wizard' },
];

export default function QuestBoard() {
  const [quests, setQuests] = useState(INITIAL_QUESTS);

  const addQuest = () => {
    setQuests(prev => [{ id: Date.now(), title: `New Quest ${prev.length + 1}` }, ...prev]);
  };

  const removeQuest = (id) => setQuests(prev => prev.filter(q => q.id !== id));

  return (
    <div>
      <button data-testid="add-btn" onClick={addQuest}>Add Quest</button>
      {/* TODO: wrap with AnimatePresence */}
      {/* TODO: motion.ul with containerVariants */}
      <ul>
        {quests.map(quest => (
          // TODO: motion.li with itemVariants, layout, exit, whileHover, whileTap
          <li key={quest.id} data-testid="quest-item">
            {quest.title}
            <button onClick={() => removeQuest(quest.id)}>Remove</button>
          </li>
        ))}
      </ul>
    </div>
  );
}
